function patternIncreasingNumberPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j < n - 1 - i; j++) row += ' ';
    for (let j = i + 1; j <= 2 * i + 1; j++) row += j;
    for (let j = 2 * i; j >= i + 1; j--) row += j;
    rows.push(row);
  }
  return rows.join('\n');
}

