function patternIncreasingNumberPyramid(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    const spaces = ' '.repeat(n - 1 - i);
    let numStr = '';
    for (let j = i + 1; j <= 2 * i + 1; j++) numStr += j;
    for (let j = 2 * i; j >= i + 1; j--) numStr += j;
    rows.push(spaces + numStr);
  }
  return rows.join('\n');
}
